INSERT INTO community_post (id, title, content, author_name, cover_url, tags) VALUES
('20000000-0000-0000-0000-000000000001', '半日茶旅如何安排更从容', '建议上午先体验茶园，再在苗寨内品茶、用餐和听文化讲解。本文为答辩演示资料。', '乌冬茶旅体验官', NULL, '茶旅,攻略,演示数据'),
('20000000-0000-0000-0000-000000000002', '在苗寨住一晚的温暖打开方式', '傍晚入住、参与长桌宴，第二天再走进山林和茶园，更能感受苗寨生活节奏。本文为答辩演示资料。', '乌冬村寨记录者', NULL, '民宿,苗寨,演示数据');
INSERT INTO knowledge_document (id, title, content, source_type, tags, index_status) VALUES
('30000000-0000-0000-0000-000000000001', '贵州乌冬苗族文化茶旅体验说明', '贵州乌冬苗族文化茶旅体验以茶园、手工制茶、品茶和苗寨文化讲解为核心。适合半日体验；如果希望节奏更舒缓，可结合苗寨山景民宿和苗家长桌宴安排两天一夜。此内容为项目答辩演示资料，不代表真实营业信息。', 'DEMO', '茶旅,苗族文化,核心场景', 'PENDING'),
('30000000-0000-0000-0000-000000000002', '贵州乌冬两天一夜茶旅建议', '第一天可安排茶园晨采、制茶品茶和苗寨文化体验，傍晚入住苗寨山景民宿并体验苗家长桌宴；第二天可根据偏好安排苗绣手作或山林漫步。服务时段和价格均为演示数据，需要在页面确认后才生成预约。', 'DEMO', '两天一夜,民宿,餐饮,茶旅', 'PENDING');
